<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/_chrome.php';
require_once __DIR__ . '/../config/contracts_module.php';
$pdo=contracts_db();$cid=contracts_company_id();contracts_require_schema($pdo);
$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$person=trim((string)($_GET['person']??''));$dueDay=(int)($_GET['due_day']??0);$dueDay=($dueDay>=1&&$dueDay<=31)?$dueDay:0;$status=(string)($_GET['status']??'');$billingMode=contracts_billing_mode_normalize((string)($_GET['billing_mode']??''));$billingModeFilter=isset($_GET['billing_mode'])&&in_array(strtoupper((string)$_GET['billing_mode']),['MANUAL','AUTOMATICA'],true)?$billingMode:'';
$where=['c.company_id=?'];$params=[$cid];
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='c.registration_date>=?';$params[]=$from;}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='c.registration_date<=?';$params[]=$to;}
if($dueDay>0){$where[]='c.due_day=?';$params[]=$dueDay;}
if(in_array($status,['TESTE','ATIVO','CANCELADO','NEGOCIACAO'],true)){$where[]='c.status=?';$params[]=$status;}
if($billingModeFilter!==''){$where[]="COALESCE(c.billing_mode,'MANUAL')=?";$params[]=$billingModeFilter;}
if($person!==''){$where[]='(c.contracting_person_name LIKE ? OR c.billing_person_name LIKE ? OR CAST(c.contract_number AS CHAR) LIKE ?)';for($i=0;$i<3;$i++)$params[]=nexa_search_like($person);}
$sql='SELECT c.*,ba.name bank_name,cc.name cost_name,ca.name chart_name FROM contracts c LEFT JOIN finance_bank_accounts ba ON ba.company_id=c.company_id AND ba.id=c.bank_account_id LEFT JOIN finance_cost_centers cc ON cc.company_id=c.company_id AND cc.id=c.cost_center_id LEFT JOIN finance_chart_accounts ca ON ca.company_id=c.company_id AND ca.id=c.chart_account_id WHERE '.implode(' AND ',$where).' ORDER BY c.id DESC LIMIT 500';
$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$counts=['TESTE'=>0,'ATIVO'=>0,'NEGOCIACAO'=>0,'CANCELADO'=>0];$sum=0;foreach($rows as $r){$counts[$r['status']] = ($counts[$r['status']]??0)+1;$sum+=(float)$r['total_amount'];}
?>
