lter="contratante"><summary title="Filtrar Cliente contratante" aria-label="Filtrar Cliente contratante">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Cliente contratante" placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="faturamento" style="width:230px"><div class="ct-th-inner"><button type="button" class="ct-sort" data-sort="faturamento" title="Ordenar por Faturamento">Faturamento <span class="ct-sort-mark"></span></button><details class="ct-col-filter" data-filter="faturamento"><summary title="Filtrar Faturamento" aria-label="Filtrar Faturamento">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Faturamento" placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="vigencia" style="width:125px"><div class="ct-th-inner"><button type="button" class="ct-sort" data-sort="vigencia" title="Ordenar por Vigência final">Vigência final <span class="ct-sort-mark"></span></button><details class="ct-col-filter" data-filter="vigencia"><summary title="Filtrar Vigência final" aria-label="Filtrar Vigência final">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Vigência final" placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="vencimento" style="width:90px"><div class="ct-th-inner"><button type="button" class="ct-sort" data-sort="vencimento" title="Ordenar por Venc.">Venc. <span class="ct-sort-mark"></span></button><details class="ct-col-filter" data-filter="vencimento"><summary title="Filtrar Venc." aria-label="Filtrar Venc.">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Venc." placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="cobranca" style="width:145px"><div class="ct-th-inner"><button type="button" class="ct-sort" data-sort="cobranca" title="Ordenar por Status cobrança">Status cobrança <span class="ct-sort-mark"></span></button><details class="ct-col-filter" data-filter="cobranca"><summary title="Filtrar Status cobrança" aria-label="Filtrar Status cobrança">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Status cobrança" placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="status" style="width:120px"><div class="ct-th-inner"><button type="button" class="ct-sort" data-sort="status" title="Ordenar por Status">Status <span class="ct-sort-mark"></span></button><details class="ct-col-filter" data-filter="status"><summary title="Filtrar Status" aria-label="Filtrar Status">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Status" placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="valor" style="width:135px"><div class="ct-th-inner"><button type="button" class="ct-sort" data-sort="valor" title="Ordenar por Valor">Valor <span class="ct-sort-mark"></span></button><details class="ct-col-filter" data-filter="valor"><summary title="Filtrar Valor" aria-label="Filtrar Valor">⌕</summary><div class="ct-filter-panel"><input aria-label="Filtrar Valor" placeholder="Filtrar coluna..." autocomplete="off"><button type="button" class="ct-clear-filter">Limpar</button></div></details></div></th><th data-col="acoes" class="ct-action-col">Ações</th></tr></thead><tbody><?php if(!$rows):?><tr class="ct-empty"><td colspan="10" class="ct-muted">Nenhum contrato encontrado.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr class="ct-data-row"><td data-col="numero"><strong>#<?=str_pad((string)$r['contract_number'],6,'0',STR_PAD_LEFT)?></strong></td><td data-col="cadastro"><?=date('d/m/Y',strtotime((string)$r['registration_date']))?></td><td data-col="contratante"><?=contracts_e($r['contracting_person_name'])?></td><td data-col="faturamento"><?=contracts_e($r['billing_person_name']?:$r['contracting_person_name'])?></td><td data-col="vigencia"><?=!empty($r['validity_end'])?date('d/m/Y',strtotime((string)$r['validity_end'])):'—'?></td><td data-col="vencimento">Dia <?= (int)$r['due_day']?></td><td data-col="cobranca"><span class="ct-badge billing-<?=contracts_e(contracts_billing_mode_normalize((string)($r['billing_mode']??'MANUAL')))?>"><?=contracts_e(contracts_billing_mode_label((string)($r['billing_mode']??'MANUAL')))?></span></td><td data-col="status"><span class="ct-badge <?=contracts_e($r['status'])?>"><?=contracts_e(contracts_status_label((string)$r['status']))?></span></td><td data-col="valor" class="num" data-sort-value="<?=contracts_e((string)$r['total_amount'])?>"><strong><?=contracts_money($r['total_amount'])?></strong></td><td data-col="acoes" class="ct-action-col"><a class="ct-btn" style="padding:7px 10px" href="contrato_editar.php?id=<?=(int)$r['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div id="personModal" class="ct-modal-bg" aria-hidden="true"><div class="ct-modal" role="dialog" aria-modal="true" aria-labelledby="personModalTitle"><div class="ct-modal-head"><strong id="personModalTitle">Buscar cliente</strong><span style="flex:1"></span><button type="button" class="ct-btn" id="closePersonLookup">Fechar</button></div><div class="ct-modal-body"><div class="ct-modal-search"><input id="personSearch" autocomplete="off" placeholder="Digite nome, documento ou telefone"><button type="button" class="ct-btn primary" id="personSearchBtn">Pesquisar</button><a class="ct-btn" href="financeiro_pessoas.php?new=1" target="_blank" rel="noopener">Cadastrar</a></div><div class="ct-hint">Pesquisa vazia ao abrir. Enter pesquisa; ↑/↓ percorrem os registros; Enter seleciona. Se digitar novamente, Enter faz uma nova pesquisa.</div><div id="personResults" class="ct-results"><div class="ct-result ct-muted">Digite a pesquisa e pressione Enter.</div></div></div></div></div>
<script>
(()=>{
  const modal=document.getElementById('personModal');
  const openBtn=document.getElementById('openPersonLookup');
  const closeBtn=document.getElementById('closePersonLookup');
  const search=document.getElementById('personSearch');
  const searchBtn=document.getElementById('personSearchBtn');
  const results=document.getElementById('personResults');
  const personFilter=document.getElementById('personFilter');
  let rows=[]; let idx=-1;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  function openModal(){modal?.classList.add('open');modal?.setAttribute('aria-hidden','false');rows=[];idx=-1;if(search){search.value='';search.dataset.last='__dirty__';}if(results)results.innerHTML='<div class="ct-result ct-muted">Digite a pesquisa e pressione Enter.</div>';setTimeout(()=>search?.focus(),30)}
  function closeModal(){modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');}
  function mark(){results?.querySelectorAll('[data-i]').forEach((el,i)=>el.classList.toggle('sel',i===idx));results?.querySelector('[data-i="'+idx+'"]')?.scrollIntoView({block:'nearest'});}
  function choose(i){const r=rows[i];if(!r)return;if(personFilter)personFilter.value=String(r.name??'');closeModal();setTimeout(()=>personFilter?.focus(),20)}
  function draw(data){rows=Array.isArray(data)?data:[];idx=rows.length?0:-1;if(!results)return;results.innerHTML=rows.map((r,i)=>`<div class="ct-result ${i===0?'sel':''}" data-i="${i}"><strong>${esc(r.name||'')}</strong><small>${esc([r.document,r.phone||r.whatsapp].filter(Boolean).join(' · '))}</small></div>`).join('')||'<div class="ct-result ct-muted">Nenhum cliente encontrado.</div>';results.querySelectorAll('[data-i]').forEach(el=>el.addEventListener('click',()=>choose(Number(el.dataset.i))))}
  async function searchPeople(){if(!search||!results)return;const q=search.value.trim();searchBtn.disabled=true;results.innerHTML='<div class="ct-result ct-muted">Pesquisando...</div>';try{const resp=await fetch('contratos_ajax.php?action=people&role=customer&q='+encodeURIComponent(q),{headers:{'Accept':'application/json'}});const j=await resp.json();if(!resp.ok||j.ok===false)throw new Error(j.message||'Falha ao pesquisar clientes.');draw(j.rows||[]);search.dataset.last=search.value;}catch(err){rows=[];idx=-1;results.innerHTML='<div class="ct-result ct-muted">'+esc(err?.message||'Não foi possível pesquisar clientes.')+'</div>';}finally{searchBtn.disabled=false;search.focus();}}
  openBtn?.addEventListener('click',openModal);closeBtn?.addEventListener('click',closeModal);searchBtn?.addEventListener('click',searchPeople);
  search?.addEventListener('input',()=>{search.dataset.last='__dirty__';rows=[];idx=-1;});
  search?.addEventListener('keydown',ev=>{if(ev.key==='ArrowDown'&&rows.length){ev.preventDefault();idx=Math.min(rows.length-1,idx+1);mark();return}if(ev.key==='ArrowUp'&&rows.length){ev.preventDefault();idx=Math.max(0,idx-1);mark();return}if(ev.key==='Enter'){ev.preventDefault();if(rows.length&&idx>=0&&search.dataset.last===search.value)choose(idx);else searchPeople();}});
  modal?.addEventListener('mousedown',ev=>{if(ev.target===modal)closeModal()});
  document.addEventListener('keydown',ev=>{if(ev.key==='F8'){ev.preventDefault();if(modal?.classList.contains('open'))search?.focus();else openModal();return}if(ev.key==='Escape'&&modal?.classList.contains('open')){ev.preventDefault();closeModal();}});
})();
</script>
<script>
(()=>{
 const grid=document.getElementById('ctContractsGrid');if(!grid)return;
 const cols=Array.from(grid.querySelectorAll('thead th[data-col]')).map(h=>h.dataset.col);
 const movable=cols.filter(c=>c!=='acoes');const labels=Object.fromEntries(movable.map(c=>[c,grid.querySelector('th[data-col="'+c+'"] .ct-sort').textContent.trim()]));
 const storage='nexa.contracts.monitor.grid.company.<?= (int)$cid ?>';
 const defaultWidths={numero:130,cadastro:115,contratante:230,faturamento:230,vigencia:125,vencimento:90,cobranca:145,status:120,valor:135,acoes:94};
 let state={order:movable.slice(),hidden:[],widths:{...defaultWidths}};
 try{const old=JSON.parse(localStorage.getItem(storage)||'null');if(old&&typeof old==='object'){
  if(Array.isArray(old.order))state.order=[...new Set(old.order.filter(c=>movable.includes(c)))].concat(movable.filter(c=>!old.order.includes(c)));
  if(Array.isArray(old.hidden))state.hidden=old.hidden.filter(c=>movable.includes(c));
  if(old.widths&&typeof old.widths==='object')for(const c of movable){const w=Number(old.widths[c]);if(Number.isFinite(w)&&w>=75&&w<=850)state.widths[c]=w;}
 }}catch(e){}
 const save=()=>{try{localStorage.setItem(storage,JSON.stringify(state));}catch(e){}};
 const dataRows=Array.from(grid.querySelectorAll('tbody tr.ct-data-row'));let sortCol='',sortDir=1;
 const tbody=grid.querySelector('tbody');const info=document.getElementById('ctGridInfo');
 function renderLayout(){
  const order=state.order.concat('acoes');
  grid.querySelectorAll('tr').forEach(tr=>{const cells=new Map(Array.from(tr.querySelectorAll('[data-col]')).map(el=>[el.dataset.col,el]));order.forEach(c=>{if(cells.has(c))tr.appendChild(cells.get(c));});});
  cols.forEach(c=>{const hidden=state.hidden.includes(c);grid.querySelectorAll('[data-col="'+c+'"]').forEach(el=>{
   el.classList.toggle('ct-col-hidden',hidden);el.style.width=(state.widths[c]||defaultWidths[c])+'px';el.style.minWidth=(state.widths[c]||defaultWidths[c])+'px';
  });});
  const total=order.filter(c=>!state.hidden.includes(c)).reduce((s,c)=>s+(state.widths[c]||defaultWidths[c]),0);
  grid.style.width=Math.max(total,grid.parentElement.clientWidth)+'px';
 }
 const toggles=document.getElementById('ctColumnToggles');
 function renderToggles(){toggles.innerHTML='';movable.forEach(c=>{const label=document.createElement('label');const cb=document.createElement('input');cb.type='checkbox';cb.checked=!state.hidden.includes(c);cb.addEventListener('change',()=>{if(cb.checked)state.hidden=state.hidden.filter(x=>x!==c);else state.hidden.push(c);renderLayout();save();});label.append(cb,document.createTextNode(labels[c]));toggles.append(label);});}
 document.getElementById('ctResetGrid')?.addEventListener('click',()=>{state={order:movable.slice(),hidden:[],widths:{...defaultWidths}};renderToggles();renderLayout();save();});
 function normal(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');}
 const inputs=new Map();grid.querySelectorAll('.ct-col-filter').forEach(detail=>{const c=detail.dataset.filter,input=detail.querySelector('input');inputs.set(c,input);
  detail.addEventListener('toggle',()=>{if(detail.open){grid.querySelectorAll('.ct-col-filter').forEach(d=>{if(d!==detail)d.open=false;});input.focus();}});
  input.addEventListener('input',applyFilters);input.addEventListener('click',e=>e.stopPropagation());
  detail.querySelector('.ct-clear-filter').addEventListener('click',()=>{input.value='';detail.open=false;applyFilters();});
 });
 function cellValue(row,c){const el=row.querySelector('td[data-col="'+c+'"]');return el?.dataset.sortValue??el?.textContent.trim()??'';}
 function applyFilters(){let n=0;dataRows.forEach(row=>{const match=Array.from(inputs).every(([c,input])=>!input.value.trim()||normal(cellValue(row,c)).includes(normal(input.value.trim())));row.hidden=!match;if(match)n++;});if(info)info.textContent='Exibindo '+n+' de '+dataRows.length+' contrato(s) (consulta limitada a 500)';grid.querySelectorAll('.ct-col-filter').forEach(d=>d.classList.toggle('active',!!d.querySelector('input').value.trim()));}
 const dateCols=new Set(['cadastro','vigencia']);const numberCols=new Set(['numero','vencimento','valor']);
 function compare(a,b,c){let av=cellValue(a,c),bv=cellValue(b,c);
  if(dateCols.has(c)){const parse=v=>{const m=v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);return m?Number(m[3]+m[2]+m[1]):-1;};return parse(av)-parse(bv);}
  if(numberCols.has(c)){const parse=v=>Number(String(v).replace(/[^\d,.-]/g,'').replace(/\./g,'').replace(',','.'))||0;return parse(av)-parse(bv);}
  return av.localeCompare(bv,'pt-BR',{numeric:true,sensitivity:'base'});
 }
 grid.querySelectorAll('[data-sort]').forEach(btn=>btn.addEventListener('click',()=>{const c=btn.dataset.sort;sortDir=c===sortCol?-sortDir:1;sortCol=c;dataRows.sort((a,b)=>sortDir*compare(a,b,c)).forEach(row=>tbody.appendChild(row));grid.querySelectorAll('.ct-sort-mark').forEach(el=>el.textContent='');btn.querySelector('.ct-sort-mark').textContent=sortDir===1?'▲':'▼';}));
 let dragging=null;
 movable.forEach(c=>{const th=grid.querySelector('th[data-col="'+c+'"]');const handle=document.createElement('span');handle.className='ct-drag';handle.textContent='⠿';handle.draggable=true;handle.title='Arrastar coluna';handle.setAttribute('aria-label','Arrastar coluna');th.querySelector('.ct-th-inner').prepend(handle);
  handle.addEventListener('dragstart',e=>{dragging=c;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',c);});handle.addEventListener('dragend',()=>{dragging=null;grid.querySelectorAll('.ct-drop').forEach(t=>t.classList.remove('ct-drop'));});
  th.addEventListener('dragover',e=>{if(!dragging||dragging===c)return;e.preventDefault();th.classList.add('ct-drop');});th.addEventListener('dragleave',()=>th.classList.remove('ct-drop'));
  th.addEventListener('drop',e=>{e.preventDefault();th.classList.remove('ct-drop');if(!dragging||dragging===c)return;state.order=state.order.filter(x=>x!==dragging);state.order.splice(state.order.indexOf(c),0,dragging);dragging=null;renderLayout();save();});
  const grip=document.createElement('span');grip.className='ct-resizer';grip.title='Ajustar largura';th.appendChild(grip);
  grip.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();const x=e.clientX,initial=state.widths[c]||defaultWidths[c];grip.setPointerCapture(e.pointerId);
   const move=ev=>{state.widths[c]=Math.max(75,Math.min(850,initial+ev.clientX-x));renderLayout();};const up=()=>{grip.removeEventListener('pointermove',move);grip.removeEventListener('pointerup',up);grip.removeEventListener('pointercancel',up);save();};grip.addEventListener('pointermove',move);grip.addEventListener('pointerup',up);grip.addEventListener('pointercancel',up);
  });
 });
 document.addEventListener('click',e=>{if(!e.target.closest('.ct-col-filter'))grid.querySelectorAll('.ct-col-filter').forEach(d=>d.open=false);if(!e.target.closest('#ctColumnsControl'))document.getElementById('ctColumnsControl').open=false;});
 renderToggles();renderLayout();applyFilters();window.addEventListener('resize',renderLayout);
})();
</script>
</div><?php admin_footer(); ?>
